package com.bank.rsocket.client;

import com.bank.rsocket.dto.TransferRequest;
import com.bank.rsocket.dto.TransferResult;
import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.circuitbreaker.CircuitBreakerConfig;
import io.github.resilience4j.reactor.circuitbreaker.operator.CircuitBreakerOperator;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.rsocket.RSocketRequester;
import reactor.core.publisher.Mono;
import reactor.util.retry.Retry;
import java.math.BigDecimal;
import java.time.Duration;
import java.util.UUID;

@Slf4j
public class TransferClient {
    private final RSocketRequester requester;
    private final CircuitBreaker breaker;

    public TransferClient(RSocketRequester requester) {
        this.requester = requester;
        this.breaker = CircuitBreaker.of("transferCB", CircuitBreakerConfig.custom()
            .failureRateThreshold(50)                       // open at 50% failures
            .waitDurationInOpenState(Duration.ofSeconds(10))// stay open 10s
            .slidingWindowSize(20)
            .permittedNumberOfCallsInHalfOpenState(3)
            .build());
    }

    public Mono<TransferResult> transfer(String from, String to, BigDecimal amount) {
        // One idempotency key per logical transfer — reused across ALL retries.
        String idemKey = UUID.randomUUID().toString();
        TransferRequest req = new TransferRequest(idemKey, from, to, amount);

        return requester.route("account.transfer").data(req)
            .retrieveMono(TransferResult.class)
            // retry transient faults inside the breaker; same idemKey → safe
            .retryWhen(Retry.backoff(3, Duration.ofSeconds(1))
                .jitter(0.5)
                .filter(this::isTransient)
                .doBeforeRetry(sig -> log.warn("Retry transfer {} attempt {}",
                        idemKey, sig.totalRetries() + 1)))
            // circuit breaker WRAPS the retry: when open, calls fail fast
            .transformDeferred(CircuitBreakerOperator.of(breaker))
            // fallback when breaker is open or all retries exhausted
            .onErrorResume(ex -> {
                log.error("Transfer {} degraded — queued for async settlement", idemKey, ex);
                return Mono.just(new TransferResult(idemKey, "QUEUED"));
            });
    }

    private boolean isTransient(Throwable t) {
        String m = t.getMessage();
        return m != null && (m.contains("timeout") || m.contains("connection"));
    }
}
